import numpy as np

def feature(values, weights, remaining, capacity, taken):
    """Gated negative dead fraction after each pick: g * (fill_i/remaining - 1), g = clip(1 - remaining/(0.30*capacity), 0, 1)."""
    k = weights.shape[0]
    if k == 0 or remaining <= 0 or capacity <= 0:
        return np.zeros(k, dtype=float)

    # Largest subset-sum reachable by the other candidates with total weight <= budget.
    # Exact DP over the candidate weights (k is small: candidates are still-fitting items).
    def largest_reachable(exclude_idx, budget):
        if budget <= 0:
            return 0
        reach = np.zeros(budget + 1, dtype=bool)
        reach[0] = True
        for j in range(k):
            if j == exclude_idx:
                continue
            wj = int(weights[j])
            if wj <= 0 or wj > budget:
                continue
            # shift-or update
            reach[wj:] |= reach[:-wj].copy()
        idx = np.nonzero(reach)[0]
        return int(idx[-1]) if idx.size else 0

    fill = np.empty(k, dtype=float)
    for i in range(k):
        budget = int(remaining) - int(weights[i])
        fill[i] = float(weights[i]) + float(largest_reachable(i, budget))

    gate = float(np.clip(1.0 - float(remaining) / (0.30 * float(capacity)), 0.0, 1.0))
    out = gate * (fill / float(remaining) - 1.0)
    return np.clip(out, -1.0, 0.0)
```

