import numpy as np

def _f_rank_gap(values, weights, remaining, capacity, taken):
    """Density rank vs fill rank disagreement: how much a candidate's efficiency standing exceeds its share-of-remaining standing, using ordinal ranks among candidates."""
    v = np.asarray(values, dtype=float)
    w = np.asarray(weights, dtype=float)
    k = v.size
    if k == 0:
        return np.zeros(0)
    rem = max(float(remaining), 1.0)
    eff = v / np.maximum(w, 1.0)
    fill = w / rem
    # ordinal ranks, 0 = worst, 1 = best; ties broken by index order
    def _rank_norm(x):
        if k == 1:
            return np.zeros(1)
        order = np.argsort(x, kind='stable')
        r = np.empty(k, dtype=float)
        r[order] = np.arange(k, dtype=float)
        return r / (k - 1.0)
    return _rank_norm(eff) - _rank_norm(fill)

def _f_take_leave_weight(value, weights, remaining, capacity, taken):
    """After taking each candidate, the largest candidate weight that still fits, relative to that residual: cheap-to-take-and-keeps-flexibility vs heavy-blocking."""
    w = np.asarray(weights, dtype=float)
    rem = max(float(remaining), 1.0)
    res = rem - w
    others = np.where(np.arange(w.size)[:, None] == np.arange(w.size)[None, :], -1.0, w[None, :])
    fits = np.where(others <= res[:, None], others, -1.0)
    best_after = fits.max(axis=1)
    best_after = np.maximum(best_after, 0.0)
    return np.clip((best_after - w) / rem, -1.0, 1.0)

def _f_count_alternatives_left(value, weights, remaining, capacity, taken):
    """Fraction of the other candidates that would still fit if this candidate is taken: measures how much choice the candidate preserves."""
    w = np.asarray(weights, dtype=float)
    k = w.size
    if k <= 1:
        return np.zeros(k)
    rem = max(float(remaining), 1.0)
    res = rem - w
    others = np.where(np.arange(k)[:, None] == np.arange(k)[None, :], np.inf, w[None, :])
    cnt = (others <= res[:, None]).sum(axis=1).astype(float)
    return 2.0 * (cnt / (k - 1.0)) - 1.0

def _f_value_rank_weight_rank_gap(values, weights, remaining, capacity, taken):
    """Both ordinal signals combined: value rank minus weight rank among candidates, i.e. how much higher the item sits on value than on weight."""
    v = np.asarray(values, dtype=float)
    w = np.asarray(weights, dtype=float)
    k = v.size
    if k == 0:
        return np.zeros(0)
    if k == 1:
        return np.zeros(1)
    def _rank_norm(x):
        order = np.argsort(x, kind='stable')
        r = np.empty(k, dtype=float)
        r[order] = np.arange(k, dtype=float)
        return r / (k - 1.0)
    return _rank_norm(v) - _rank_norm(w)

_TERMS = [(_f_rank_gap, 1.0), (_f_take_leave_weight, 1.0),
          (_f_count_alternatives_left, 1.0), (_f_value_rank_weight_rank_gap, 1.0)]

def priority(values, weights, remaining, capacity, taken):
    total = None
    for f, wt in _TERMS:
        t = np.asarray(f(values, weights, remaining, capacity, taken), dtype=float)
        total = t * wt if total is None else total + t * wt
    return np.round(np.nan_to_num(total, nan=0.0, posinf=1e3, neginf=-1e3), 9)
